\section*{Question 2}

The graphs of the polar curves \(r=3\) and \(r=4-2 \sin \theta\) are shown in the figure above. The curves intersect when \(\theta=\frac{\pi}{6}\) and \(\theta=\frac{5 \pi}{6}\).
\begin{itemize}
\item[(a)] Let \(S\) be the shaded region that is inside the graph of \(r=3\) and also inside the graph of \(r=4-2 \sin \theta\). Find the area of \(S\).
\item[(b)] A particle moves along the polar curve \(r=4-2 \sin \theta\) so that at time \(t\) seconds, \(\theta=t^{2}\). Find the time \(t\) in the interval \(1 \leq t \leq 2\) for which the \(x\)-coordinate of the particle's position is -1.
\item[(c)] For the particle described in part (b), find the position vector in terms of \(t\). Find the velocity vector at time \(t=1.5\).
\item[(a)] Area \(=6 \pi+\frac{1}{2} \int_{\pi / 6}^{5 \pi / 6}(4-2 \sin \theta)^{2} d \theta=24.709\) (or 24.708)
\item[(b)]
\[
\begin{aligned}
& x=r \cos \theta \Rightarrow x(\theta)=(4-2 \sin \theta) \cos \theta \\
& x(t)=\left(4-2 \sin \left(t^{2}\right)\right) \cos \left(t^{2}\right) \\
& x(t)=-1 \text { when } t=1.428(\text { or } 1.427)
\end{aligned}
\]
\end{itemize}
\(3:\left\{\begin{array}{l}1: \text { integrand } \\ 1: \text { limits and constant } \\ 1: \text { answer }\end{array}\right.\)
\(3:\left\{\begin{array}{l}1: x(\theta) \text { or } x(t) \\ 1: x(\theta)=-1 \text { or } x(t)=-1 \\ 1: \text { answer }\end{array}\right.\)
\(3:\left\{\begin{array}{l}2: \text { position vector } \\ 1: \text { velocity vector }\end{array}\right.\)
\begin{itemize}
\item[(c)]
\[
\begin{aligned}
& y=r \sin \theta \Rightarrow y(\theta)=(4-2 \sin \theta) \sin \theta \\
& y(t)=\left(4-2 \sin \left(t^{2}\right)\right) \sin \left(t^{2}\right)
\end{aligned}
\]
\[
\begin{aligned}
\text { Position vector } & =\langle x(t), y(t)\rangle \\
& =\left\langle\left(4-2 \sin \left(t^{2}\right)\right) \cos \left(t^{2}\right),\left(4-2 \sin \left(t^{2}\right)\right) \sin \left(t^{2}\right)\right\rangle
\end{aligned}
\]
\[
\begin{aligned}
v(1.5) & =\left\langle x^{\prime}(1.5), y^{\prime}(1.5)\right\rangle \\
& =\langle-8.072,-1.673\rangle(\text { or }\langle-8.072,-1.672\rangle)
\end{aligned}
\]
\end{itemize}
